mapper.update:
update risk_model_version_rule
rule_name = #{body.rule_name}, metric_key = #{body.metric_key}, operator_type = #{body.operator_type}, threshold_value = #{body.threshold_value}, effect_type = #{body.effect_type}, score_value = #{body.score_value}, risk_tag = #{body.risk_tag}, reason_template = #{body.reason_template}, enabled = #{body.enabled}, sort_order = #{body.sort_order},
where version_id = #{versionId} and rule_code = #{ruleCode}

update risk_model_version
set simulation_summary = #{summaryJson}, simulated_at = #{simulatedAt}
where id = #{versionId}

update risk_model_version
set status = 'IN_REVIEW', submitted_by = #{operator}, submitted_at = #{submittedAt}
where id = #{versionId}

update risk_model_version
set status = 'APPROVED', approved_by = #{operator}, approval_comment = #{comment}, approved_at = #{approvedAt}
where id = #{versionId}

update risk_model_version
set status = 'RETIRED'
where status = 'PUBLISHED' and id != #{versionId}

update risk_model_version
set status = 'PUBLISHED', approved_by = #{operator}, published_at = #{publishedAt}
where id = #{versionId}

update risk_alert_case
set alert_state = 'RESOLVED', closure_comment = #{comment}, closed_at = #{closedAt}
where customer_no = #{customerNo} and alert_state in ('OPEN', 'IN_PROGRESS', 'OVERDUE', 'PENDING_REVIEW', 'REJECTED')

update risk_alert_case
set alert_state = 'OVERDUE', escalation_level = least(escalation_level + 1, 3)
where alert_state in ('OPEN', 'IN_PROGRESS') and sla_due_at < #{now}

mapper.select:
select id, alert_case_id, risk_code, treatment_plan_id, risk_event_id, risk_indicator_id, last_sync_state, last_sync_at, created_at, updated_at
from risk_alert_case_link
where alert_case_id = #{alertCaseId}

mapper.update:
update risk_register
set `level` = #{body.level}, owner_department = #{body.owner_department}, responsible_person = #{body.responsible_person},
    status = #{body.status}, due_date = #{body.due_date}, description = #{body.description}
where id = #{id}

update risk_treatment_plan
set owner = #{body.owner}, due_date = #{body.due_date}, progress = #{body.progress}, status = #{body.status}
where id = #{id}

update risk_event
set severity = #{body.severity}, owner = #{body.owner}, status = #{body.status}, summary = #{body.summary}
where id = #{id}

update risk_indicator
set current_value = #{body.current_value}, trend = #{body.trend}, owner = #{body.owner}, status = #{body.status}
where id = #{id}
